function Jarvis-ReadResponse {
    param(
        [string]$SentPrompt,
        [hashtable]$Before,
        [int]$TimeoutSeconds = 1200,
        [int]$StableSeconds = 5
    )
    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
    $beforeText = if ($Before -and $Before.Text) { [string]$Before.Text } else { '' }
    $promptTrim = $SentPrompt.Trim()
    $prevDoc = $null
    $stableSince = $null
    $started = $false
    $startedAt = Get-Date
    $lastStatus = Get-Date

    while ((Get-Date) -lt $deadline) {
        if (((Get-Date) - $lastStatus).TotalSeconds -ge 15) {
            Write-Host ('  Freebuff is working... {0}s elapsed' -f [int]((Get-Date) - $startedAt).TotalSeconds) -ForegroundColor DarkGray
            $lastStatus = Get-Date
        }
        $cur = Jarvis-CurrentLastText
        if ($null -eq $cur -and ((Get-Date) - $startedAt).TotalSeconds -ge 30) {
            # Freebuff is not readable (no CDP endpoint and no UI Automation
            # content) - don't sit here for the full timeout.
            return $null
        }
        if ($cur -and $cur.Text) {
            $textTrim = ([string]$cur.Text).Trim()
            $isPromptEcho = $textTrim -eq $promptTrim -or
                ([string]$cur.Text).TrimEnd().EndsWith($promptTrim)

            if (-not $started) {
                if ($cur.Mode -eq 'doc') {
                    $docGrew = $cur.Text.Length -gt $beforeText.Length + 2 -and -not $isPromptEcho
                    if ($docGrew) { $started = $true; $prevDoc = $cur.Text; $stableSince = Get-Date }
                } else {
                    $changed = $textTrim -ne $promptTrim -and $textTrim -ne $beforeText.Trim() -and $textTrim.Length -gt 0
                    if ($changed) { $started = $true; $prevDoc = $cur.Text; $stableSince = Get-Date }
                }
            } else {
                if ($cur.Text -ne $prevDoc) { $prevDoc = $cur.Text; $stableSince = Get-Date }
                elseif (((Get-Date) - $stableSince).TotalSeconds -ge $StableSeconds) {
                    if ($cur.Mode -eq 'doc') {
                        $newPart = $cur.Text.Substring([Math]::Min($beforeText.Length, $cur.Text.Length))
                        $newPart = $newPart.TrimStart()
                        if ($newPart.Length -ge $promptTrim.Length -and
                            $newPart.Substring(0, $promptTrim.Length) -eq $promptTrim) {
                            $newPart = $newPart.Substring($promptTrim.Length).TrimStart()
                        }
                        return $newPart.Trim()
                    }
                    return $textTrim
                }
            }
        }
        Start-Sleep -Milliseconds 700
    }
    return $null
}

